import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

// Fixed: nothing asserts on it, and new Date() would tie the run to the clock.
const SENT_AT = '2026-01-01T00:00:00.000Z';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

// The provider rejects with the value as-is, which is deliberately not an Error.
function rejectingWith(value: unknown): AIProvider {
  return {
    // eslint-disable-next-line require-yield
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      // eslint-disable-next-line @typescript-eslint/only-throw-error -- the rejection under test is not an Error
      throw value;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

type Settled = {threw: false} | {threw: true; caught: unknown};

async function settle(call: Promise<unknown>): Promise<Settled> {
  try {
    await call;
    return {threw: false};
  } catch (caught) {
    return {threw: true, caught};
  }
}

describe('onError for a rejection that is not an Error', () => {
  it.each([
    ['a string', 'provider exploded'],
    ['a plain object', {code: 'RATE_LIMITED', retryAfter: 30}],
    ['undefined', undefined],
  ])('calls onError once with an Error whose cause is %s, and still rejects the caller unchanged', async (_label, value) => {
    const onErrorArgs: unknown[] = [];
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        onErrorArgs.push(error);
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith(value), promptBuilder, undefined, {hooks});
    const outcome = await settle(orchestrator.processMessage(createSession('hello')));

    expect(outcome).toEqual({threw: true, caught: value});
    expect(onErrorArgs).toHaveLength(1);
    expect(onErrorArgs[0]).toBeInstanceOf(Error);
    expect(onErrorArgs[0]).toHaveProperty('cause', value);
  });
});

